"""Extra independent checks with smarter (still exact) solvers on larger
random instances, plus a timing/polynomiality sanity check."""
import random, time
from reduce import reduce


def dpll_sat(num_vars, clauses):
    # clauses: list of lists of ints
    def simplify(clauses, assign):
        new = []
        for cl in clauses:
            sat = False
            rem = []
            for lit in cl:
                v = abs(lit)
                if v in assign:
                    val = assign[v]
                    if (lit > 0) == val:
                        sat = True
                        break
                else:
                    rem.append(lit)
            if sat:
                continue
            if not rem:
                return None  # empty clause -> unsat under assign
            new.append(rem)
        return new

    def solve(clauses, assign):
        clauses = simplify(clauses, assign)
        if clauses is None:
            return False
        if not clauses:
            return True
        # unit propagation
        while True:
            unit = None
            for cl in clauses:
                if len(cl) == 1:
                    unit = cl[0]
                    break
            if unit is None:
                break
            assign = dict(assign)
            assign[abs(unit)] = unit > 0
            clauses = simplify(clauses, assign)
            if clauses is None:
                return False
            if not clauses:
                return True
        # pick a variable
        lit = clauses[0][0]
        v = abs(lit)
        for val in (True, False):
            a = dict(assign)
            a[v] = val
            if solve(clauses, a):
                return True
        return False

    return solve(clauses, {})


def backtrack_exact_cover(u, sets):
    masks = []
    for s in sets:
        m = 0
        for e in s:
            m |= 1 << e
        masks.append(m)
    full = (1 << u) - 1
    n = len(sets)
    # order by size descending
    order = sorted(range(n), key=lambda i: -bin(masks[i]).count("1"))
    from functools import lru_cache
    import sys
    sys.setrecursionlimit(10000)

    def rec(idx, covered):
        if covered == full:
            return True
        if idx == len(order):
            return False
        # prune: remaining sets can't cover
        i = order[idx]
        m = masks[i]
        if m & covered == 0:  # disjoint
            if rec(idx + 1, covered | m):
                return True
        if rec(idx + 1, covered):
            return True
        return False

    return rec(0, 0)


def random_instance(rng, max_u, max_sets):
    u = rng.randint(0, max_u)
    k = rng.randint(0, max_sets)
    sets = []
    for _ in range(k):
        size = rng.randint(0, u)
        sets.append(rng.sample(range(u), size))
    return {"universe_size": u, "sets": sets}


rng = random.Random(999)
run = passed = 0
fails = []
for _ in range(4000):
    inst = random_instance(rng, max_u=8, max_sets=10)
    out = reduce(inst)
    exp = backtrack_exact_cover(inst["universe_size"], inst["sets"])
    got = dpll_sat(out["num_vars"], out["clauses"])
    run += 1
    if exp == got:
        passed += 1
    else:
        fails.append((inst, exp, got))

