for f in fails[:5]:
    print("FAIL", f)

# Timing / polynomiality sanity: reduce on a large instance should be fast.
big = {"universe_size": 200, "sets": [list(range(i, min(i + 5, 200))) for i in range(0, 200, 2)]}
t = time.time()
out = reduce(big)
dt = time.time() - t
print("big reduce time=%.3fs num_vars=%d clauses=%d" % (dt, out["num_vars"], len(out["clauses"])))
